#!/usr/bin/env python3
"""Sort raw plankton tow CSVs into per-year subfolders."""
import os, re, shutil

RAW = os.path.join(os.path.dirname(os.path.abspath(__file__)), "raw")

def year_of(filename):
    # filenames look like tow_2024-03-11.csv
    m = re.search(r"(\d{4})-\d{2}-\d{2}", filename)
    return m.group(1)

def main():
    counts = {}
    for name in os.listdir(RAW):
        if not name.endswith(".csv"):
            continue
        year = year_of(name)
        dest_dir = os.path.join(RAW, year)
        os.makedirs(dest_dir, exist_ok=True)
