                    conn.sendall(('%s OK [READ-WRITE] SELECT completed\r\n' % tag).encode())
                elif 'LIST' in cmd:
                    conn.sendall(b'* LIST (\\HasNoChildren) "/" "INBOX"\r\n')
                    conn.sendall(('%s OK LIST completed\r\n' % tag).encode())
                elif 'STATUS' in cmd:
                    conn.sendall(b'* STATUS "INBOX" (MESSAGES 1 UNSEEN 0)\r\n')
                    conn.sendall(('%s OK STATUS completed\r\n' % tag).encode())
                elif 'LOGOUT' in cmd:
                    conn.sendall(b'* BYE\r\n')
                    conn.sendall(('%s OK LOGOUT completed\r\n' % tag).encode())
                    break
                else:
                    conn.sendall(('%s OK command completed\r\n' % tag).encode())
    except Exception as e:
        LOG.write('IMAP ERR: %r\n' % e)
