        try: conn.close()
        except: pass

def smtp_conn(conn, addr):
    try:
        conn.sendall(b'220 localhost ESMTP\r\n')
        while True:
            data = conn.recv(4096)
            if not data:
                break
            line = data.decode('utf-8', 'replace').strip()
            LOG.write('SMTP C: ' + line + '\n')
            u = line.upper()
            if u.startswith('EHLO') or u.startswith('HELO'):
                conn.sendall(b'250-localhost Hello\r\n250-PIPELINING\r\n250 8BITMIME\r\n')
            elif u.startswith('QUIT'):
                conn.sendall(b'221 2.0.0 Bye\r\n')
                break
            else:
